<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/functions.php';require_login();$q='%'.trim($_GET['q']??'').'%';$s=$conn->prepare('SELECT t.*,p.nama,l.nama_layanan FROM transaksi t JOIN pelanggan p ON t.id_pelanggan=p.id_pelanggan JOIN layanan l ON t.id_layanan=l.id_layanan WHERE t.nomor_nota LIKE ? OR p.nama LIKE ? ORDER BY t.tanggal_transaksi DESC');$s->bind_param('ss',$q,$q);$s->execute();$rows=$s->get_result();$pageTitle='Riwayat';$active='riwayat';include __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h1>Riwayat Transaksi</h1><p class="muted">Cari berdasarkan nama pelanggan atau nomor nota.</p></div><a class="btn btn-primary" href="index.php">Transaksi Baru</a></div><section class="panel"><form class="d-flex gap-2 mb-3"><input class="form-control" name="q" placeholder="Nama pelanggan / nomor nota" value="<?=e($_GET['q']??'')?>"><button class="btn btn-outline-primary">Cari</button></form><div class="table-responsive"><table class="table"><thead><tr><th>No. Nota</th><th>Tanggal</th><th>Pelanggan</th><th>Layanan</th><th>Berat</th><th>Total</th><th>Metode</th><th>Nota</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['nomor_nota'])?></td><td><?=date('d/m/Y H:i',strtotime($r['tanggal_transaksi']))?></td><td><?=e($r['nama'])?></td><td><?=e($r['nama_layanan'])?></td><td><?=e($r['berat_pakaian'])?> kg</td><td><?=rupiah($r['total_pembayaran'])?></td><td><?=e($r['metode_pembayaran'])?></td><td><a class="btn btn-sm btn-light" href="/laundrypos/nota/cetak.php?id=<?=$r['id_transaksi']?>">Buka</a></td></tr><?php endwhile;?></tbody></table></div></section><?php include __DIR__.'/../includes/footer.php';?>